  "id": "graphics-bouncing-tiles",
  "order": 1,
  "title": "Bouncing tiles",
  "description": "A Flow gfx app in the Preview panel. Change a colour or speed and it rebuilds in about a second.",
  "files": [
   {
    "name": "app.flow",
    "language": "flow",
    "text": "# A Flow graphics app. Run it, then edit a colour or a speed below and\n# watch the Preview rebuild. Click the canvas to give it the keyboard.\n#\n# Controls: move the mouse over the tiles, hold Space to pause the ball.\n\nimport \"stdlib/gfx.flow\"\nimport \"stdlib/text.flow\"\n\nconst W: i32 = 640\nconst H: i32 = 400\nconst TILE: i32 = 40\nconst BALL: i32 = 14\nconst KEY_SPACE: i32 = 49\n\n# Try changing these while the app runs.\nconst SPEED_X: i32 = 4\nconst SPEED_Y: i32 = 3\nconst BALL_R: i32 = 250\nconst BALL_G: i32 = 196\nconst BALL_B: i32 = 92\n\nfunction main() -> i32 {\n    let g = gfx_open(W, H, \"Bouncing tiles\")\n    let mut x: i32 = 60\n    let mut y: i32 = 80\n    let mut dx: i32 = SPEED_X\n    let mut dy: i32 = SPEED_Y\n    let mut frame: i32 = 0\n    let mut bounces: i32 = 0\n    while gfx_frame_pump(g) {\n        gfx_clear(g, 18, 20, 26)\n        let mx: i32 = gfx_mouse_x(g)\n        let my: i32 = gfx_mouse_y(g)\n        let mut ty: i32 = 0\n        while ty < H / TILE {\n            let mut tx: i32 = 0\n            while tx < W / TILE {\n                let shade: i32 = (tx * 9 + ty * 13 + frame / 2) % 60\n                let mut r: i32 = 30 + shade / 2\n                let mut gr: i32 = 44 + shade\n                let mut b: i32 = 64 + shade\n                if mx / TILE == tx and my / TILE == ty {\n                    r = 120\n                    gr = 210\n                    b = 170\n                }\n                gfx_fill_rect(g, tx * TILE + 1, ty * TILE + 1, TILE - 2, TILE - 2, r, gr, b)\n                tx = tx + 1\n            }\n            ty = ty + 1\n        }\n        if !gfx_key_down(g, KEY_SPACE) {\n            x = x + dx\n            y = y + dy\n        }\n        if x < 0 or x > W - BALL {\n            dx = 0 - dx\n            bounces = bounces + 1\n        }\n        if y < 0 or y > H - BALL {\n            dy = 0 - dy\n            bounces = bounces + 1\n        }\n        gfx_fill_rect(g, x, y, BALL, BALL, BALL_R, BALL_G, BALL_B)\n        let pen: i32 = gfx_draw_text(g, 12, 12, \"BOUNCES \", 2, 230, 232, 238)\n        gfx_draw_int(g, 12 + pen, 12, bounces, 2, BALL_R, BALL_G, BALL_B)\n        gfx_present(g)\n        gfx_wait_frame(g, 60)\n        frame = frame + 1\n    }\n    gfx_close(g)\n    return 0\n}\n"
   }
  ],
